import{_ as t,o,c as s,a0 as a}from"./chunks/framework.BxCN1dRw.js";const u=JSON.parse('{"title":"Walkthrough: Using production components and registering demo scenes","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/design-system"},"headers":[],"relativePath":"en/tutorials/design-system.md","filePath":"en/tutorials/design-system.md"}'),n={name:"en/tutorials/design-system.md"};function i(r,e,c,d,l,h){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="walkthrough-using-production-components-and-registering-demo-scenes" tabindex="-1">Walkthrough: Using production components and registering demo scenes <a class="header-anchor" href="#walkthrough-using-production-components-and-registering-demo-scenes" aria-label="Permalink to &quot;Walkthrough: Using production components and registering demo scenes&quot;">​</a></h1><p>The design-system showroom (<code>/design-system</code>) is a reference room for the &quot;replace the template with your own product&quot; step: every signed-in user can reach it from the bottom of the sidebar, and the colors, typography, spacing, components and icons it shows are the exact ones the business pages use — the showroom keeps no second color table and no separate copy of the library, so what you see here is what ships. This chapter walks the four tabs (Foundation / Components / Scenes / Icons), how an example registers its own demo scenes, and what happens to the showroom when an example is removed.</p><h2 id="_1-feel-it-first-from-settings-to-the-showroom" tabindex="-1">1. Feel it first: from settings to the showroom <a class="header-anchor" href="#_1-feel-it-first-from-settings-to-the-showroom" aria-label="Permalink to &quot;1. Feel it first: from settings to the showroom&quot;">​</a></h2><p>Run <code>just dev</code>, sign in, and open &quot;Design system&quot; at the bottom of the sidebar — or use the same showroom embedded in the settings page&#39;s &quot;Design system&quot; section; both entries render one component and share one lazy chunk. The page has four tabs: <strong>Foundation</strong> lists color tokens, typography and spacing/radius; <strong>Components</strong> lets you actually operate buttons, form controls, overlays and feedback components; <strong>Scenes</strong> holds the generic form, list and empty-state scenes plus scenes registered by examples; <strong>Icons</strong> is an on-demand icon catalog searchable by name. Switch to English, switch to dark, and look again — all four language/theme combinations share the same production components; there is no second skin.</p><h2 id="_2-foundation-and-components-reading-production-tokens-directly" tabindex="-1">2. Foundation and components: reading production tokens directly <a class="header-anchor" href="#_2-foundation-and-components-reading-production-tokens-directly" aria-label="Permalink to &quot;2. Foundation and components: reading production tokens directly&quot;">​</a></h2><p>The token values on the Foundation tab are not a hard-coded swatch sheet — they are computed values read live from the document with <code>getComputedStyle</code> at render time: re-enter the page under the dark theme and the list shows the dark tokens&#39; current values. &quot;Copy&quot; takes the value as computed right now — if the template re-skins, this list follows automatically. Typography and spacing/radius render with the production utilities themselves (<code>text-sm</code>, <code>p-4</code>, <code>rounded-lg</code>…).</p><p>The Components tab operates real <code>@saas/ui</code> components: the six button variants, loading (<code>aria-busy</code> plus a spinner), disabled; input, textarea, select and switch; &quot;Simulate validation error&quot; produces an <code>aria-invalid</code> flag, error text and a destructive alert together — error state never rides on color alone. The overlay demo uses the same AlertDialog as the production delete confirmation: focus moves into the dialog when it opens, Esc or Cancel closes it, and &quot;Confirm delete&quot; only leaves a demo note in local state — no request is sent.</p><h2 id="_3-scenes-isolated-fixtures-and-example-registration" tabindex="-1">3. Scenes: isolated fixtures and example registration <a class="header-anchor" href="#_3-scenes-isolated-fixtures-and-example-registration" aria-label="Permalink to &quot;3. Scenes: isolated fixtures and example registration&quot;">​</a></h2><p>The generic form, list and empty-state scenes on the Scenes tab run on isolated fixtures and component-local state: saving sends no request, selection affects only this page, and the empty state toggles between its two shapes — they demonstrate shapes, not a business feature.</p><p>An example can register its own scenes through the assembly point (<code>ExampleContribution.scenes</code>, declaring an <code>id</code>, bilingual message keys and an optional interactive render body): the notes example (unregistered by default; once added back with <code>scripts/example-add.mjs</code>) registers a &quot;Notes example&quot; scene whose title resolves through the example&#39;s own namespace (<code>notes.nav.notes</code>), with the source example labeled on the card. After the removal tool strips the example, its scenes disappear with it — in a Core-only combination the Scenes tab keeps only the generic scenes, with a &quot;no example scenes in this combination&quot; note, and the base showroom stays complete. The knowledge base&#39;s save-conflict scene (UI07), attachment-icons-and-upload-states scene (UI08) and export-states-and-notification-display scene (UI09) all shipped through this same registration channel; their render bodies demo the save outcomes, the attachment upload lifecycle, and the display mapping from status badges to notification titles with the production components, on demo data only.</p><h2 id="_4-icons-an-on-demand-catalog" tabindex="-1">4. Icons: an on-demand catalog <a class="header-anchor" href="#_4-icons-an-on-demand-catalog" aria-label="Permalink to &quot;4. Icons: an on-demand catalog&quot;">​</a></h2><p>The Icons tab has three parts. The top half is the <strong>ModuleIcon matrix</strong>: ten category colors across four appearances (bare / flat / soft / glossy), rendered once per table under scoped light and dark previews — category colors mark modules in small areas only (sidebar, module entries) and stay independent of semantic state colors; Core modules register theirs in <code>packages/views/src/shell/module-registry.ts</code>, and an example module declares its own route colors through <code>ExampleContribution.moduleIcons</code>, removed together with the example. The middle is the <strong>file-icon samples</strong>: attachments and file lists resolve to a vendored subset of Material Icon Theme 5.38.1 (32 SVGs, MIT license, attribution in <code>THIRD-PARTY-NOTICES.md</code> at the repository root) by filename, then longest extension, then MIME; export rows show version, status and expiry without a filename, so they carry no file icon yet. The bottom half is the curated Lucide catalog organized into four categories (Actions / Navigation / Status / Objects) whose category colors come from production tokens (<code>text-primary</code>, <code>text-link</code>, <code>text-success</code>, <code>text-warning</code>). The whole Icons tab ships in its own async chunk, downloaded the first time you open it — the initial bundle never contains it, and the performance budgets (<code>scripts/perf/baselines.json</code>) stay untouched. Each icon button carries a localized accessible name (&quot;Copy icon name X&quot;), clicking copies the icon name, and the copy feedback is text, not color. The Lucide icons come from <a href="https://lucide.dev" target="_blank" rel="noreferrer">lucide.dev</a> under the ISC license and can be swapped for any compatible icon set; to extend the catalog, add a row to the category table in <code>icon-catalog.tsx</code>.</p><h2 id="_5-accessible-interaction" tabindex="-1">5. Accessible interaction <a class="header-anchor" href="#_5-accessible-interaction" aria-label="Permalink to &quot;5. Accessible interaction&quot;">​</a></h2><p>The showroom does not lower the accessibility bar for demo purposes: the tabs are a real <code>tablist/tab</code> set, overlay focus is managed by the dialog primitive, icon buttons have localized names, copy feedback goes to a <code>role=&quot;status&quot;</code> text region, and the focus ring always uses the <code>ring</code> token. Search fields, radios and switches are native controls or components with complete ARIA state, fully keyboard operable. Demo data is fully isolated from the signed-in user&#39;s business data: scenes never query or write real resources — which is exactly why the showroom can open to every signed-in user.</p><h2 id="_6-verify-it" tabindex="-1">6. Verify it <a class="header-anchor" href="#_6-verify-it" aria-label="Permalink to &quot;6. Verify it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/design-system.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/app-shell.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>The design-system suite drives entry visibility, token search and copy feedback, component state operation, overlay focus, scene isolation, icon search and copy, and all four language/theme combinations through the real router; the app-shell suite keeps the sidebar entry signed-in-only. Scene assertions are written combination-agnostically — the removal job runs the same file and verifies that example scenes vanish while the base showroom stays. The bundle-budget measurement inside <code>just check</code> confirms the showroom and icon catalog live only in async chunks — the <code>lazyPatterns</code> list in <code>scripts/perf/baselines.json</code> turns that lazy boundary into a gate, so a regression that pulls the showroom back into the initial bundle fails outright. When registering a new example, declaring <code>scenes</code> on its <code>ExampleContribution</code> adds it to the Scenes tab with no showroom changes.</p><hr><p>Source version：<code>957a0b05c2cb</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/957a0b05c2cb3d0ed820d65a99a561cbb86fffd8/docs/tutorials/29-design-system.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,19)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
